import{_ as e,o as l,c as d,a2 as o}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"快速鍵與互動手勢","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/hotkeys.md","filePath":"zh-TW/user-guide/hotkeys.md","lastUpdated":1790959149000}'),r={name:"zh-TW/user-guide/hotkeys.md"};function a(s,t,n,g,i,c){return l(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="快速鍵與互動手勢" tabindex="-1">快速鍵與互動手勢 <a class="header-anchor" href="#快速鍵與互動手勢" aria-label="Permalink to &quot;快速鍵與互動手勢&quot;">​</a></h1><p>Lertaro 採用鍵盤優先的互動設計，同時提供極其豐富的滑鼠快捷手勢與多級導覽系統。除固定按鍵外，所有全域與應用程式內快速鍵均可在<a href="./settings/hotkeys-page.html"><strong>設定 → 快速鍵</strong></a>中自由重新綁定。</p><h2 id="_1-全域快速鍵速查表" tabindex="-1">1. 全域快速鍵速查表 <a class="header-anchor" href="#_1-全域快速鍵速查表" aria-label="Permalink to &quot;1. 全域快速鍵速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">功能動作</th><th style="text-align:left;">預設快速鍵</th><th style="text-align:left;">功能說明與互動細節</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>呼出/隱藏快速視窗</strong></td><td style="text-align:left;">按兩下 <code>Ctrl</code></td><td style="text-align:left;">可設定為連按兩下模式或常規組合鍵（例如 <code>Alt+Space</code>、<code>Win+Space</code> 等）。所謂連按兩下，是指按下<strong>同一個</strong>修飾鍵兩次、兩次放開之間相隔 <strong>100–300 毫秒</strong>——左 <code>Ctrl</code> 與右 <code>Ctrl</code> 屬於不同按鍵，期間按下任何其他鍵都會讓計數重新開始。採用連按兩下模式時，修飾鍵本身絕不會被吞掉，因此 <code>Ctrl</code>+<code>C</code> 這類普通快速鍵照常可用。啟用「預設開啟完整面板」後，此快速鍵會改為開啟主視窗：首次顯示時只將其置於前景並聚焦一次，視窗已顯示但未啟用時重新啟用，視窗已啟用時再次按下則關閉；不會自動保持置頂。</td></tr><tr><td style="text-align:left;"><strong>快速切換（Quick Jump）</strong></td><td style="text-align:left;"><code>Ctrl+G</code></td><td style="text-align:left;">在檔案對話方塊中直接跳轉到最近一次從受支援檔案管理器或快速面板中瀏覽的資料夾。</td></tr><tr><td style="text-align:left;"><strong>快速導覽選單</strong></td><td style="text-align:left;">無預設快速鍵</td><td style="text-align:left;">可選的全域快速鍵，用於開啟階層式快速導覽選單。在桌面或普通應用程式中呼出時使用桌面情境；在檔案總管和原生檔案對話方塊中呼出時使用目前視窗情境。即使普通前景保護會抑制全域快速鍵，檔案管理器和檔案對話方塊仍會放行。</td></tr><tr><td style="text-align:left;"><strong>選取下一項</strong></td><td style="text-align:left;"><code>Ctrl+N</code> 或 <code>↓</code></td><td style="text-align:left;">向下移動清單反白項目。在快速面板中支援無縫跨群組連續瀏覽；在快速啟動面板中，方向鍵按照可見網格移動，左右鍵會跨越行邊界，上下鍵會在相鄰方向尋找最近的同欄項目，也會跨越群組；只有相鄰方向中整欄都沒有項目時才保持目前位置；快速啟動面板顯示且搜尋內容為空時，<code>Ctrl+N</code> 會循環切換到下一個資料來源。</td></tr><tr><td style="text-align:left;"><strong>選取上一項</strong></td><td style="text-align:left;"><code>Ctrl+P</code> 或 <code>↑</code></td><td style="text-align:left;">向上移動清單反白項目。在快速面板中同樣支援跨群組巡覽；在快速啟動面板中，方向鍵按照可見網格移動，左右鍵會跨越行邊界，上下鍵會在相鄰方向尋找最近的同欄項目，也會跨越群組；只有相鄰方向中整欄都沒有項目時才保持目前位置；快速啟動面板顯示且搜尋內容為空時，<code>Ctrl+P</code> 會循環切換到上一個資料來源。</td></tr><tr><td style="text-align:left;"><strong>跳轉至第 1–9 項結果</strong></td><td style="text-align:left;"><code>Ctrl</code> + <code>1</code>–<code>9</code></td><td style="text-align:left;">修飾鍵可自訂，快速視窗結果旁會顯示對應的數字徽章，直接按鍵秒開目標項目。數字代表<strong>從第一個可見行算起</strong>的第 N 個可選取列，因此捲動時徽章會隨之重新編號；<code>0</code> 並未綁定。快速啟動面板是例外——它綁定 <code>1</code>–<code>9</code>、<code>0</code> 與 <code>A</code>–<code>Z</code>，最多可對應 36 個平鋪項目。</td></tr><tr><td style="text-align:left;"><strong>開啟動作功能表</strong></td><td style="text-align:left;"><code>Ctrl+O</code> 或 <code>→</code></td><td style="text-align:left;">展開選取結果的快顯動作面板（複製路徑、屬性、以系統管理員身分執行、檔案操作等）。快速視窗以及<strong>檔案對話方塊以外</strong>的內嵌卡片都能使用；主視窗則改用按一下滑鼠右鍵或 <code>Apps</code> 鍵（<code>Shift+F10</code>）開啟同一個動作功能表。</td></tr><tr><td style="text-align:left;"><strong>從選取項補全搜尋詞</strong></td><td style="text-align:left;"><code>Ctrl+Tab</code></td><td style="text-align:left;">將目前選取項目的名稱或完整路徑直接填入搜尋框，便於在此基礎上做二次篩選。</td></tr><tr><td style="text-align:left;"><strong>QuickLook 即時預覽</strong></td><td style="text-align:left;"><code>Alt+P</code></td><td style="text-align:left;">開啟/關閉選取項目的側邊預覽面板（圖片、文件、音訊/影片即時播放、資料夾結構等）。快速視窗、主視窗與快速面板皆可使用，內嵌卡片不適用；在可預覽的列上按一下滑鼠中鍵也能切換同一個預覽面板。</td></tr><tr><td style="text-align:left;"><strong>上一條搜尋記錄詞</strong></td><td style="text-align:left;"><code>Alt+Up</code></td><td style="text-align:left;">向前翻閱最近輸入過的搜尋關鍵字。</td></tr><tr><td style="text-align:left;"><strong>下一條搜尋記錄詞</strong></td><td style="text-align:left;"><code>Alt+Down</code></td><td style="text-align:left;">向後翻閱最近輸入過的搜尋關鍵字。</td></tr><tr><td style="text-align:left;"><strong>刪除目前歷史詞</strong></td><td style="text-align:left;"><code>Ctrl+Delete</code></td><td style="text-align:left;">從最近搜尋歷程記錄中移除目前顯示的這一條詞彙。</td></tr><tr><td style="text-align:left;"><strong>開啟完整搜尋主視窗</strong></td><td style="text-align:left;"><code>Ctrl+F</code></td><td style="text-align:left;">直接開啟大尺寸主搜尋視窗，並自動同步目前快速視窗中的搜尋詞。</td></tr><tr><td style="text-align:left;"><strong>開啟傳送視窗（LocalSend）</strong></td><td style="text-align:left;"><code>Ctrl+S</code></td><td style="text-align:left;">開啟 LocalSend 無線區域網路傳輸視窗，快速傳送檔案或文字至跨平台裝置。</td></tr><tr><td style="text-align:left;"><strong>保持視窗不消失（釘住）</strong></td><td style="text-align:left;"><code>Ctrl+T</code></td><td style="text-align:left;">臨時鎖定視窗，在失去焦點時不再自動隱藏（便於從其他視窗複製文字組合查詢）。</td></tr><tr><td style="text-align:left;"><strong>呼出/關閉快速面板</strong></td><td style="text-align:left;"><code>Ctrl+F2</code></td><td style="text-align:left;">在目前前景活動視窗旁展開包含最近檔案、我的最愛、工作區的快速停靠面板。</td></tr></tbody></table><h3 id="檔案對話方塊中的空白搜尋" tabindex="-1">檔案對話方塊中的空白搜尋 <a class="header-anchor" href="#檔案對話方塊中的空白搜尋" aria-label="Permalink to &quot;檔案對話方塊中的空白搜尋&quot;">​</a></h3><p>當內嵌搜尋框位於原生檔案對話方塊中且搜尋內容為空時，清單會先顯示「上次目錄」分組。開啟「在內嵌搜尋中顯示目前開啟的資料夾」後，還會顯示彙總受支援檔案管理器正在瀏覽目錄的「目前開啟的資料夾」分組。目前檔案對話方塊所在目錄會被排除，重複路徑會自動去重，空分組不會顯示，分組標題也不會顯示快速鍵徽章。此開關預設開啟，可在<a href="./settings/general.html"><strong>設定 → 一般 → 系統</strong></a>中修改。此行為只適用於檔案對話方塊中的內嵌搜尋，快速視窗和完整視窗不受影響。</p><h3 id="內嵌視窗的呼出與焦點交接" tabindex="-1">內嵌視窗的呼出與焦點交接 <a class="header-anchor" href="#內嵌視窗的呼出與焦點交接" aria-label="Permalink to &quot;內嵌視窗的呼出與焦點交接&quot;">​</a></h3><p>停靠在原生檔案對話方塊中的卡片刻意<strong>不搶佔鍵盤</strong>：焦點仍留在對話方塊，你可以繼續在它自己的檔案名稱欄位中打字，卡片則同步反映搜尋內容。會移動游標的手勢有：</p><table tabindex="0"><thead><tr><th style="text-align:left;">手勢</th><th style="text-align:left;">效果</th><th style="text-align:left;">條件</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>輸入字母或數字</strong></td><td style="text-align:left;">呼出卡片，同時把那個第一個字元帶進搜尋框；後續按鍵會持續輸入其中</td><td style="text-align:left;">僅限真實按鍵——自動化工具合成的輸入會原樣放行而不予攔截，內容功能表或系統功能表開啟期間也不會擷取任何按鍵</td></tr><tr><td style="text-align:left;"><strong>按兩下 <code>Ctrl</code></strong>（或你設定的呼出快速鍵）</td><td style="text-align:left;">把游標放進卡片自己的搜尋框。若搜尋框已取得游標且內容為空，則改為清空搜尋詞，並把焦點交還給對話方塊的欄位，卡片保持開啟</td><td style="text-align:left;">與其他地方用的是同一個快速鍵，所以在<a href="./settings/hotkeys-page.html"><strong>設定 → 快速鍵</strong></a>中改綁，這裡也會跟著變。即使黑名單或全螢幕通常會使全域快速鍵沉默，檔案對話方塊仍然適用</td></tr><tr><td style="text-align:left;"><strong><code>Escape</code></strong></td><td style="text-align:left;"><strong>對話方塊</strong>持有鍵盤時，卡片關閉。<strong>卡片</strong>持有鍵盤時，清空搜尋詞並將焦點交還對話方塊（檔案對話方塊中），或關閉卡片（停靠在普通檔案總管視窗上時）</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>在空框按 <code>Backspace</code></strong></td><td style="text-align:left;">與 <code>Escape</code> 完全相同地離開搜尋</td><td style="text-align:left;">僅在卡片取得游標時；對話方塊持有鍵盤時，該鍵只會編輯卡片的搜尋詞</td></tr><tr><td style="text-align:left;"><strong>在空框按 <code>Enter</code></strong></td><td style="text-align:left;">像 <code>Escape</code> 一樣離開搜尋</td><td style="text-align:left;">僅在卡片取得游標時——對話方塊持有鍵盤時，<code>Enter</code> 會開啟反白的瀏覽列</td></tr><tr><td style="text-align:left;"><strong><code>Tab</code></strong></td><td style="text-align:left;">永遠留給對話方塊自己的控制項遍歷，因此請改用呼出快速鍵進入卡片</td><td style="text-align:left;"></td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>在檔案對話方塊內，卡片無法使用動作功能表（<code>Ctrl+O</code>、<code>→</code> 與滑鼠右鍵在那裡都沒有作用），也不提供 <code>Alt+P</code> 預覽。滑鼠在清單列上仍然可用：<strong>按一下左鍵</strong>開啟反白的結果，<strong><code>Ctrl</code>+按一下</strong>以系統管理員身分開啟，列可以<strong>拖曳出去</strong>放進對話方塊，而單純<strong>停留在列上</strong>就會移動選取——宿主檔案管理器也會同步跟進。</p></div><h2 id="_2-搜尋框圖示與滑鼠手勢" tabindex="-1">2. 搜尋框圖示與滑鼠手勢 <a class="header-anchor" href="#_2-搜尋框圖示與滑鼠手勢" aria-label="Permalink to &quot;2. 搜尋框圖示與滑鼠手勢&quot;">​</a></h2><p>搜尋框內的小圖示不僅是品牌識別，更集成了多種實用的滑鼠快捷手勢：</p><h3 id="快速搜尋視窗中的圖示手勢" tabindex="-1">快速搜尋視窗中的圖示手勢 <a class="header-anchor" href="#快速搜尋視窗中的圖示手勢" aria-label="Permalink to &quot;快速搜尋視窗中的圖示手勢&quot;">​</a></h3><ul><li><strong>滑鼠左鍵按一下</strong>：直接在游標處彈出快捷主功能表（顯示主視窗、切換快速鍵配置、開啟設定、關於、乾淨結束、結束程式）。其中「顯示主視窗」會自動攜帶目前輸入的內容。</li><li><strong>滑鼠左鍵按住拖曳</strong>：自由拖曳調整搜尋列在螢幕上的顯示位置。<strong>拖曳時按住 <code>Ctrl</code> 鍵</strong>可將移動方向嚴格鎖定為<strong>純垂直方向</strong>，避免水平位置發生偏移。</li><li><strong>滑鼠右鍵按一下</strong>：一鍵將快速視窗重設回螢幕初始預設置中位置（不改變已配置的視窗尺寸）。</li><li><strong>滑鼠中鍵按一下</strong>：快捷切換視窗「釘住（保持不消失）」狀態，釘住期間 Logo 圖示會反白發光。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>快速視窗記錄的螢幕座標是相對於所在顯示器的<strong>相對比例座標</strong>。當你將視窗喚出在另一台不同解析度、不同 DPI 縮放的顯示器上時，Lertaro 會自動等比換算位置，絕不會跑出螢幕可視區域。</p></div><h3 id="內嵌視窗與主視窗中的圖示" tabindex="-1">內嵌視窗與主視窗中的圖示 <a class="header-anchor" href="#內嵌視窗與主視窗中的圖示" aria-label="Permalink to &quot;內嵌視窗與主視窗中的圖示&quot;">​</a></h3><ul><li><strong>內嵌視窗</strong>：當嵌入在原生檔案對話方塊（開啟/儲存/瀏覽）時，按一下左鍵圖示可直接展開<a href="#3-快速導覽滑鼠觸發"><strong>快速導覽</strong></a>階層式功能表；停靠在普通檔案總管時僅作展示。拖曳圖示會移動卡片本身，而之後每次停靠都會重新套用該偏移量。</li><li><strong>主視窗</strong>：按一下左鍵圖示會開啟快顯功能表；由於主視窗已經開啟，功能表中的「顯示主視窗」項目會隱藏。按一下中鍵可切換視窗的釘住狀態。</li></ul><h3 id="搜尋框手勢-快速視窗" tabindex="-1">搜尋框手勢（快速視窗） <a class="header-anchor" href="#搜尋框手勢-快速視窗" aria-label="Permalink to &quot;搜尋框手勢（快速視窗）&quot;">​</a></h3><ul><li><strong>在搜尋框上滾動滑鼠滾輪</strong>：向前/向後翻閱最近的搜尋詞——與 <code>Alt+Up</code> / <code>Alt+Down</code> 的導覽完全相同，手不必離開滑鼠。</li><li><strong>以滑鼠中鍵按一下搜尋框</strong>：刪除目前顯示的那筆歷史記錄。此手勢是硬編碼的，並非可設定的 <code>Ctrl+Delete</code> 綁定。</li><li><strong>隨時輸入任何文字</strong>都會結束本次歷史瀏覽，因此下一格滾輪會重新從你目前的搜尋詞開始。歷史不會循環：翻到最舊一詞就停在那裡，翻到最新一詞則回到你最初開始的那個搜尋詞。</li></ul><h3 id="系統匣圖示" tabindex="-1">系統匣圖示 <a class="header-anchor" href="#系統匣圖示" aria-label="Permalink to &quot;系統匣圖示&quot;">​</a></h3><ul><li><strong>按一下左鍵</strong>：切換快速視窗，效果與呼出快速鍵完全相同。</li><li><strong>按一下右鍵</strong>（或第二次按一下，因為並沒有按兩下的處理程式）：在游標處開啟功能表——顯示主視窗、傳送至其他裝置（僅在 LocalSend 啟用期間）、停用/啟用快速鍵、設定、關於、乾淨結束（僅在 Lertaro 是唯一執行中的處理程序時）與結束程式。</li><li><strong>隱藏系統匣圖示</strong>（<a href="./settings/general.html"><strong>設定 → 一般 → 系統</strong></a>）只會移除圖示，絕不會移除視窗內的 Logo 功能表。當快速鍵透過該功能表被停用時，圖示會被強制恢復顯示，讓你不會把自己鎖在外面。</li></ul><h2 id="_3-快速導覽-滑鼠觸發" tabindex="-1">3. 快速導覽（滑鼠觸發） <a class="header-anchor" href="#_3-快速導覽-滑鼠觸發" aria-label="Permalink to &quot;3. 快速導覽（滑鼠觸發）&quot;">​</a></h2><p>快速導覽功能讓你無需打字，透過滑鼠按一下即可在任意視窗中直達常用目錄或開啟檔案。</p><p>你也可以在<a href="./settings/hotkeys-page.html"><strong>設定 → 快速鍵</strong></a>中為快速導覽選單指定一個可選的全域快速鍵。在桌面或普通應用程式中呼出時使用桌面情境；在檔案總管和原生檔案對話方塊中呼出時使用目前視窗情境。</p><h3 id="觸發方式與支援環境" tabindex="-1">觸發方式與支援環境 <a class="header-anchor" href="#觸發方式與支援環境" aria-label="Permalink to &quot;觸發方式與支援環境&quot;">​</a></h3><ul><li><strong>桌面空白處</strong>：滑鼠中鍵按一下（或開啟按兩下左鍵）直接彈出快速導覽功能表，按一下目錄或檔案直接開啟。</li><li><strong>檔案總管</strong>：在檔案總管空白處按一下滑鼠中鍵觸發，按一下目標後目前視窗立即跳轉到該路徑。</li><li><strong>第三方檔案管理器</strong>：在 Directory Opus、Total Commander、XYplorer、Files、One Commander 等工具的檔案清單區按一下滑鼠中鍵觸發（詳見<a href="./file-manager-support.html"><strong>支援的檔案管理器</strong></a>）。</li><li><strong>系統檔案對話方塊</strong>：在任意軟體的「開啟/儲存/瀏覽資料夾」對話方塊中按一下中鍵或按一下內嵌圖示觸發，按一下後對話方塊直接跳轉至目標目錄，絕不會誤觸發「儲存/開啟」確認。</li></ul><h3 id="階層式功能表內容與管理" tabindex="-1">階層式功能表內容與管理 <a class="header-anchor" href="#階層式功能表內容與管理" aria-label="Permalink to &quot;階層式功能表內容與管理&quot;">​</a></h3><p>快速導覽功能表由**階層式資料夾瀏覽器（Folder Cascader）**外掛模組驅動，內容高度結構化：</p><ol><li><strong>目前開啟的資料夾</strong>：自動彙總並去重所有受支援檔案管理器目前正在瀏覽的真實目錄，方便在不同應用程式間快速同步路徑。</li><li><strong>我的最愛與歷程記錄</strong>：自動按分類列出你的加星收藏與最近造訪歷程。</li><li><strong>自訂快捷分類</strong>：支援在<strong>設定 → 外掛模組 → 階層式資料夾瀏覽器</strong>中自訂目錄與子功能表（如使用 <code>工作/專案A</code> 建立多級分類）。</li><li><strong>一鍵新增目錄（<code>+</code> 按鈕）</strong>：功能表每個層級的標題右側均設有一個 <code>+</code> 按鈕，按一下即可直接將目前正在瀏覽的資料夾快速儲存到該分類下，無需開啟設定面板。</li></ol><h2 id="_4-硬編碼核心按鍵-不可修改" tabindex="-1">4. 硬編碼核心按鍵（不可修改） <a class="header-anchor" href="#_4-硬編碼核心按鍵-不可修改" aria-label="Permalink to &quot;4. 硬編碼核心按鍵（不可修改）&quot;">​</a></h2><p>為了保證最核心互動的確定性與一致性，以下按鍵在任何配置下行為始終保持統一：</p><table tabindex="0"><thead><tr><th style="text-align:left;">按鍵</th><th style="text-align:left;">觸發場景</th><th style="text-align:left;">統一行為</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">結果清單</td><td style="text-align:left;">直接開啟選取的結果（檔案/目錄/程式/動作）。在主視窗中會開啟<strong>每一個</strong>選取列。內嵌搜尋框為空時則改為離開搜尋——此時沒有排在最前的結果可開啟。</td></tr><tr><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">結果清單</td><td style="text-align:left;">在檔案總管中開啟並定位選取項目所在目錄。</td></tr><tr><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">結果清單</td><td style="text-align:left;">以系統管理員權限啟動選取的程式或檔案。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">快速視窗</td><td style="text-align:left;">隱藏視窗。這一次按鍵絕不會清空搜尋框——搜尋詞是留下還是清除，改由<strong>關閉後保留搜尋框內容</strong>決定。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">主視窗</td><td style="text-align:left;">清空搜尋詞並讓搜尋框重新取得焦點；搜尋框已為空時則關閉視窗，而若<strong>關閉後保留搜尋框內容</strong>已開啟就會直接關閉視窗（所以你不必無謂地按第二次）。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">內嵌卡片</td><td style="text-align:left;">詳見上文<strong>內嵌視窗的呼出與焦點交接</strong>：對話方塊持有鍵盤時它會關閉卡片，卡片持有鍵盤時則交還焦點。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">動作功能表</td><td style="text-align:left;">一次按一層：先清空動作篩選詞，接著退出子功能表，最後離開動作功能表並還原原本的搜尋詞。</td></tr><tr><td style="text-align:left;"><code>Backspace</code></td><td style="text-align:left;">動作功能表</td><td style="text-align:left;">當搜尋過濾詞已為空時，按下直接退出動作功能表返回結果清單。</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code> 方向鍵</td><td style="text-align:left;">動作功能表</td><td style="text-align:left;">左箭頭返回上一級功能表，右箭頭進入子功能表。<code>Tab</code> 同樣能進入子功能表，除非你已把它綁定為選取上一項/下一項的快速鍵。</td></tr><tr><td style="text-align:left;"><code>Tab</code></td><td style="text-align:left;">內嵌卡片</td><td style="text-align:left;">會被吸收，使焦點無法離開搜尋框；而對話方塊內部的 <code>Tab</code> 仍照常遍歷它自己的控制項。</td></tr><tr><td style="text-align:left;"><code>Tab</code></td><td style="text-align:left;">動作功能表</td><td style="text-align:left;">進入反白的子功能表——除非你已把 <code>Tab</code> 綁定為選取上一項/下一項的快速鍵，此時該綁定優先。</td></tr><tr><td style="text-align:left;"><code>Apps</code> / <code>Shift+F10</code></td><td style="text-align:left;">主視窗</td><td style="text-align:left;">為目前選取的項目開啟動作功能表，效果與按一下滑鼠右鍵完全相同。</td></tr><tr><td style="text-align:left;"><code>Alt+Space</code></td><td style="text-align:left;">所有 Lertaro 視窗</td><td style="text-align:left;">強制遮蔽系統標題列功能表，防止誤觸快顯視窗。</td></tr><tr><td style="text-align:left;"><code>Alt+F4</code></td><td style="text-align:left;">主視窗 / 設定視窗</td><td style="text-align:left;">關閉目前視窗。在快速視窗、內嵌視窗、快速面板、預覽浮動視窗、LocalSend 視窗以及程式內對話方塊上會被遮蔽（防止誤關閉常駐服務）。</td></tr></tbody></table><h2 id="_5-外掛模組動作快速鍵與處理程序黑名單" tabindex="-1">5. 外掛模組動作快速鍵與處理程序黑名單 <a class="header-anchor" href="#_5-外掛模組動作快速鍵與處理程序黑名單" aria-label="Permalink to &quot;5. 外掛模組動作快速鍵與處理程序黑名單&quot;">​</a></h2><h3 id="外掛模組獨立動作快速鍵" tabindex="-1">外掛模組獨立動作快速鍵 <a class="header-anchor" href="#外掛模組獨立動作快速鍵" aria-label="Permalink to &quot;外掛模組獨立動作快速鍵&quot;">​</a></h3><p>內建檔案動作的預設快速鍵為：剪下 <code>Ctrl+X</code>、複製檔案 <code>Ctrl+C</code>、貼上 <code>Ctrl+V</code>、刪除 <code>Delete</code>、徹底刪除 <code>Shift+Delete</code>、複製路徑 <code>Ctrl+Shift+C</code>、複製名稱 <code>Shift+C</code>、在檔案總管中定位 <code>Ctrl+Enter</code>、以系統管理員身分執行 <code>Ctrl+Shift+Enter</code>。</p><p>兩個防護讓具破壞性的按鍵在搜尋框底下依然安全。組合鍵只在搜尋框<strong>沒有反白文字</strong>時才會觸發動作，因此 <code>Ctrl+X</code> / <code>Ctrl+C</code> / <code>Ctrl+V</code> 照舊剪下、複製與貼上你的搜尋詞。像 <code>Delete</code> 這樣的單獨按鍵，只在游標<strong>已位於搜尋詞末尾</strong>、沒有字元剩下來給它刪除時才會觸發動作；游標在文字中間時它仍然是打字按鍵。而兩個刪除動作都經過 Shell 自己的 <code>IFileOperation</code>，所以在按鍵與檔案之間仍會先出現原生的「是否移入資源回收筒？」／「是否永久刪除？」確認。要重新綁定或清除其中任何一個，請到<strong>設定 → 快速鍵 → 外掛模組動作</strong>。</p><h3 id="處理程序黑名單與全螢幕自動放行" tabindex="-1">處理程序黑名單與全螢幕自動放行 <a class="header-anchor" href="#處理程序黑名單與全螢幕自動放行" aria-label="Permalink to &quot;處理程序黑名單與全螢幕自動放行&quot;">​</a></h3><ul><li><strong>全螢幕應用程式自動放行</strong>：當偵測到前景有獨占全螢幕執行的應用程式（如全螢幕 3D 遊戲、全螢幕影片播放器）時，Lertaro 預設會自動放行所有全域快速鍵，絕不搶佔遊戲控制。</li><li><strong>自訂處理程序黑名單</strong>：在<a href="./settings/hotkeys-page.html#process-blacklist"><strong>設定 → 快速鍵頁面</strong></a>中新增特定處理程序名稱（如 <code>game.exe</code>），當該程式處於前景時，全域快速鍵與滑鼠快速導覽將完全無訊息放行。</li></ul>',38)])])}const x=e(r,[["render",a]]);export{h as __pageData,x as default};
